void main(){test('twenty-eight pictogram batches cover the complete 386-item catalog',(){final full=<Set<String>>[codeFoodPictogramIds,codeFoodPictogramBatch2Ids,codeFoodPictogramBatch3Ids,codeFoodPictogramBatch4Ids,codeFoodPictogramBatch5Ids,codeFoodPictogramBatch6Ids,codeFoodPictogramBatch7Ids,codeFoodPictogramBatch8Ids,codeFoodPictogramBatch9Ids,codeFoodPictogramBatch10Ids,codeFoodPictogramBatch11Ids,codeFoodPictogramBatch12Ids,codeFoodPictogramBatch13Ids,codeFoodPictogramBatch15Ids];for(final b in full){expect(b.length,24);}expect(codeFoodPictogramBatch14Ids.length,10);expect(codeFoodPictogramBatch16Ids.length,3);expect(codeFoodPictogramBatch17Ids.length,4);expect(codeFoodPictogramBatch18Ids.length,3);expect(codeFoodPictogramBatch19Ids.length,3);expect(codeFoodPictogramBatch20Ids.length,3);expect(codeFoodPictogramBatch21Ids.length,3);expect(codeFoodPictogramBatch22Ids.length,3);expect(codeFoodPictogramBatch23Ids.length,3);expect(codeFoodPictogramBatch24Ids.length,3);expect(codeFoodPictogramBatch25Ids.length,3);expect(codeFoodPictogramBatch26Ids.length,3);expect(codeFoodPictogramBatch27Ids.length,3);expect(codeFoodPictogramBatch28Ids.length,3);final batches=<Set<String>>[...full,codeFoodPictogramBatch14Ids,codeFoodPictogramBatch16Ids,codeFoodPictogramBatch17Ids,codeFoodPictogramBatch18Ids,codeFoodPictogramBatch19Ids,codeFoodPictogramBatch20Ids,codeFoodPictogramBatch21Ids,codeFoodPictogramBatch22Ids,codeFoodPictogramBatch23Ids,codeFoodPictogramBatch24Ids,codeFoodPictogramBatch25Ids,codeFoodPictogramBatch26Ids,codeFoodPictogramBatch27Ids,codeFoodPictogramBatch28Ids];for(var i=0;i<batches.length;i++){for(var j=i+1;j<batches.length;j++){expect(batches[i].intersection(batches[j]),isEmpty);}}final union=batches.expand((b)=>b).toSet();expect(union.length,386);expect(union,mealFoodCatalog.map((e)=>e.id).toSet());});}
